+                id: "full-name",
+                label: "Full name",
+                placeholder: "Alex Morgan",
+                required: true,
+                autoComplete: "name",
+              }),
+              h(FormField, {
+                id: "email",
+                label: "Email address",
+                type: "email",
+                placeholder: "alex@example.com",
+                required: true,
+                autoComplete: "email",
+              }),
+              h(FormField, {
+                id: "phone",
+                label: "Phone number",
