        margin: 0 0 0.75rem;
        color: var(--primary);
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 6vw, 3.4rem);
        line-height: 1.05;
        letter-spacing: -0.05em;
      }

      .intro {
        max-width: 34rem;
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.65;
      }

      .contact-form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      label {
        font-size: 0.95rem;
        font-weight: 700;
      }

      .optional {
        color: var(--muted);
        font-weight: 600;
      }

      input {
        width: 100%;
        min-height: 3.2rem;
        padding: 0.85rem 1rem;
        color: var(--text);
        font: inherit;
        background: #ffffff;
        border: 1px solid var(--border);
        border-radius: 0.9rem;
        outline: none;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          transform 160ms ease;
      }

      input::placeholder {
        color: #9aa4b2;
      }

      input:focus {
        border-color: var(--primary);
        box-shadow: 0 0 0 4px var(--focus);
      }

      input:hover {
        border-color: #b9c3d3;
      }

      .helper-text {
        margin: 0;
        color: var(--muted);
        font-size: 0.9rem;
        line-height: 1.45;
      }

      .submit-button {
        justify-self: start;
        min-height: 3.15rem;
        margin-top: 0.5rem;
        padding: 0.85rem 1.35rem;
        color: #ffffff;
        font: inherit;
        font-weight: 800;
        background: var(--primary);
        border: 0;
        border-radius: 999px;
        box-shadow: 0 14px 28px rgba(37, 99, 235, 0.28);
        cursor: pointer;
        transition:
          background 160ms ease,
          box-shadow 160ms ease,
          transform 160ms ease;
      }

      .submit-button:hover {
        background: var(--primary-dark);
        box-shadow: 0 18px 34px rgba(37, 99, 235, 0.34);
        transform: translateY(-1px);
      }

      .submit-button:focus-visible {
        outline: 4px solid var(--focus);
        outline-offset: 3px;
