            h("p", { className: "helper-text", id: helperId }, helperText)
        );
      }

      function ContactForm() {
        return h(
          "main",
          { className: "page-shell" },
          h(
            "section",
            { className: "support-card", "aria-labelledby": "support-heading" },
            h("p", { className: "eyebrow" }, "Support"),
            h("h1", { id: "support-heading" }, "How can we help?"),
            h(
              "p",
              { className: "intro" },
              "Tell us how to reach you and our support team will follow up with a clear next step."
            ),
            h(
              "form",
              { className: "contact-form", noValidate: true },
              h(FormField, {
                id: "full-name",
                label: "Full name",
                placeholder: "Alex Morgan",
                required: true,
                autoComplete: "name",
              }),
              h(FormField, {
                id: "email",
                label: "Email address",
                type: "email",
                placeholder: "alex@example.com",
                required: true,
                autoComplete: "email",
              }),
              h(FormField, {
                id: "phone",
                label: "Phone number",
                type: "tel",
                placeholder: "+1 555 123 4567",
                helperText:
                  "Use international format when possible, for example +1 555 123 4567.",
                autoComplete: "tel",
              }),
              h("button", { className: "submit-button", type: "submit" }, "Submit request")
            )
          )
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(h(ContactForm));
    </script>
  </body>
</html>
